import React from 'react';
import { Link } from 'react-scroll';

export const Home = () => {
  return (
    <div id="home" className="home-section">
      <div className="content-box">
        <h1>Tanaya Siddiqui</h1>
        <h2>Front-end Developer</h2>
        <p>Developer with a focus on web development and data analysis. Skilled in Python, C, JS, HTML, CSS, React, learning C++ and Unreal Engine.</p>
        <Link to="about" className="about-link" smooth={true} duration={500}>Go to About</Link>
      </div>
    </div>
  );
};

export default Home;
